manifests.package.json:
{
  "name": "copyboard",
  "version": "0.1.1",
  "description": "Cumulo Workflow",
  "main": "index.js",
  "packageManager": "yarn@4.18.0",
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "check": "calcit calcit.cirru fix --workflow strict --verify && calcit calcit.cirru --check-only --ns app.client --ns app.comp.container --ns app.comp.copied --ns app.comp.home --ns app.comp.login --ns app.comp.navigation --ns app.comp.profile --ns app.comp.upload --ns app.config --ns app.schema --ns app.style && calcit calcit.cirru --entry server --check-only --ns app.server --ns app.config --ns app.schema --ns app.twig.container --ns app.twig.user --ns app.updater --ns app.updater.router --ns app.updater.session --ns app.updater.snippet --ns app.updater.user && calcit calcit.cirru analyze weak-types --only deprecated-call --summary-only && calcit calcit.cirru --entry server analyze weak-types --only deprecated-call --summary-only",
    "compile-page": "calcit calcit.cirru js",
    "dev": "vite",
    "release-page": "vite build --base=${VITE_BASE_URL:-./}",
    "server": "calcit calcit.cirru --entry server",
    "smoke-server": "node scripts/smoke-native-server.mjs",
    "watch-page": "calcit -w calcit.cirru js"
  },
  "repository": {
    "type": "git",
    "url": "git@github.com:mvc-works/cumulo-workflow.git"
  },
  "author": "jiyinyiyong",
  "license": "MIT",
  "dependencies": {
    "@calcit/procs": "0.30.1-alpha.4",
    "axios": "^1.20.0",
    "mime": "^4.1.0"
  },
  "devDependencies": {
    "bottom-tip": "^0.1.5",
    "copy-text-to-clipboard": "^3.2.2",
    "feather-icons": "^4.29.2",
    "spark-md5": "^3.0.2",
    "url-parse": "^1.5.10",
    "vite": "^8.1.6"
  }
}
